      const payChannel = upperTrim(line?.pay_channel || '');
      const payeTreatment = upperTrim(line?.paye_treatment || '');
      const section = getLinePresentationSection(line);
      const caseRecoveryRoute = upperTrim(renderContextSection || section) === 'CASES_RESOLUTIONS'
        ? getCaseResolutionPayRoutePresentation(line)
        : null;
      const blockedRecoveryPresentation = section === 'BLOCKED_FOR_PAY'
        ? getOverpaymentRecoveryPresentation(line)
        : null;
      const insufficientRecoveryFunds = blockedRecoveryPresentation?.no_available_funds === true;
      const blockedUi = getPreviewLineBlockedUi(line);
      const actionHtml = previewActionHtml(line);
      const caseActionHtml = (section === 'CASES_RESOLUTIONS' && isPlainObject(line?.__case_entry))
        ? renderCaseActionButtons(line.__case_entry)
        : '';
      const cancelResolvedRateHtml = resolvedRateCancelActionHtml(line, renderContextSection);
      const combinedActionHtml = [caseActionHtml, cancelResolvedRateHtml, blockedUi.extraActionHtml, actionHtml].filter(Boolean).join(' ');
      const expenseComponentLabel = isExactTimesheetExpenseLine(line) ? getExpenseComponentFriendlyLabel(line) : '';
      const compactReady = upperTrim(renderContextSection || section) === 'READY_TO_PAY';
      const detailRowHtml = renderPreviewLineBreakdown(
        line,
        renderContextSection,
        compactReady ? { expandedBodyOnly: true } : {}
      );
      const info = getSnoozeInfo(line);
      const stateLabel = insufficientRecoveryFunds ? 'Insufficient funds' : (stateLabelOverride || (
        section === 'BLOCKED_FOR_PAY'
          ? 'Blocked for pay'
          : (section === 'CASES_RESOLUTIONS'
              ? 'Resolution required'
              : (info.isDated
                  ? `Snoozed until ${ymdToUk(info.snoozeUntil) || info.snoozeUntil}`
                  : (asBool(line?.is_ready_for_draft) ? 'Ready to pay' : 'Review required')))
      ));
      const statePillClass = section === 'BLOCKED_FOR_PAY'
        ? 'pill-bad'
        : (section === 'CASES_RESOLUTIONS' ? 'pill-warn' : ((info.isDated || upperTrim(line?.line_type || '') === 'BLOCKED_TIMESHEET' || upperTrim(line?.line_type || '') === 'DO_NOT_PAY' || asBool(line?.is_excluded_from_allocation) || (line?.is_ready_for_draft === false) || asBool(line?.case_is_blocked)) ? 'pill-bad' : 'pill-ok'));
      const isBlockedLike = section === 'BLOCKED_FOR_PAY' || section === 'CASES_RESOLUTIONS' || info.isDated || upperTrim(line?.line_type || '') === 'BLOCKED_TIMESHEET' || upperTrim(line?.line_type || '') === 'DO_NOT_PAY' || asBool(line?.is_excluded_from_allocation) || (line?.is_ready_for_draft === false) || asBool(line?.case_is_blocked);
      const previewRowId = getPreviewRowId(line);
      const presentationGroupRowIds = uniqTrimmed(asArray(line?.__presentation_group_selectable_row_ids));
      const selectedPresentationGroupRowIds = presentationGroupRowIds.filter((rowId) => selectedPreviewRowSet.has(rowId));
      const presentationGroupSelectionState = presentationGroupRowIds.length <= 0
        ? 'NONE'
        : (selectedPresentationGroupRowIds.length === presentationGroupRowIds.length
            ? 'ALL'
            : (selectedPresentationGroupRowIds.length === 0 ? 'NONE' : 'PARTIAL'));
      const selectionAllowed = presentationGroupRowIds.length > 0 || isPreviewRowSelectionAllowed(line);
      const selected = presentationGroupRowIds.length > 0
        ? presentationGroupSelectionState === 'ALL'
        : (selectionAllowed && isPreviewRowSelected(line));
      const timesheetId = trimStr(line?.timesheet_id || line?.linked_timesheet_id || '');
      const candidateId = trimStr(line?.candidate_id || '');
      const lineType = upperTrim(line?.line_type || '');
      const selectionScope = 'SINGLE_PREVIEW_ROW';
      const readyBreakdownKey = compactReady && detailRowHtml
        ? `READY_DETAIL|${previewRowId || trimStr(line?.row_key || line?.rowKey || line?.line_key || line?.lineKey || '')}`
        : '';
      const readyBreakdownOpen = !!(readyBreakdownKey && openReadyTimesheetBreakdownKeys.has(readyBreakdownKey));

      const rowAnchor = makeScrollAnchor('preview', previewRowId);
